; DOS L preset: Laura Bow 1 (The Colonel's Bequest), Korean UTF-8 translation
; (GAMES\LB1KO: MESSAGE.MAP + RESOURCE.MSG, packed text resources +
; SCI-KO.STR, language=ko). KO2350.SVF (16 px, 1 bpp) beside this file;
; characters it lacks draw U+25A1.
;
; Canonical name (common2350-brief, 2026-09-29): this replaces the shipped
; lb1 zip's LB1U8L.MAP (same content, KO2350.SVF in place of the old
; per-game subset LB1KOL.SVF); the coverage gate found LB1's translation
; needs nothing outside the 2350.
;
; LB1's font ids, their line height in hi-res px and the game baseline row:
;   0   status/menu bar, parser line, system dialogs    16  row 14
;   1   large message boxes ("막이 오르려")              24  row 16
;   4   dialogue, narration, copy-protection screen      18  row 14
;   8   cast names under the intro portraits             24  row 20
;   40  the "1925 / LA 뉴올리언스" caption               36  row 30
;   41  opening credits and act titles ("제I막")        36  row 30
; The L preset's ink is rows 1-13 (baseline row 12, descenders to row 14); on
; the game baseline it fits every line but font 0's, which is moved up a row.
; Fonts 40/41 keep the 16 px cell: the glyphs are 16 px wide.
[hires]
scale=2
alpha=false
face=ko
missing=u+25a1

[fonts]
ko=KO2350.SVF

[latin]
mode=proportional
metrics=font

; status line, menu bar, parser line, system dialogs: 16 px lines; ink on
; rows 2-15 instead of 3-16
[font.0]
baseline=-1

; the cast names are lined up under the portraits with runs of spaces:
; spaces and Latin keep the game font's widths (metrics=game)
[font.8]
metrics=game
